// The label lives here, in the browser only \u2014 the API never sees it.
cellRendererParams: {
  mapValueToText: (value) => this.statusLabels[value] ?? value,
}

// So invert the map before querying, or the user's "Not Bootstrapped"
// never reaches the backend in terms it understands.
const fields = [device.name, device.status];
if (labelAware) {
  fields.push(this.statusLabels[device.status]);
}

